sg_improve_supply_network = {
	category = sgcat_tutorial

	unlocking_subgoals_any = {
		sg_expand_productive_building
	}

	trigger = {
		any_scope_state = {
			AND = {
				is_coastal = yes
				sg:merchant_marine = {
					state_goods_pricier > 0.3
				}
			}
		}
	}

	on_start = {
		if = {
			limit = {
				any_scope_state = {
					AND = {
						is_coastal = yes
						sg:merchant_marine = {
							state_goods_pricier > 0.3
						}
					}
				}
			}
			random_scope_state = {
				limit = {
					AND = {
						is_coastal = yes
						sg:merchant_marine = {
							state_goods_pricier > 0.3
						}
					}
				}
				sg:merchant_marine = { save_scope_as = tut_supply_network }
			}
		}

		add_journal_entry = {
			type = je_tutorial_improve_supply_network
			objective_subgoal = sg_improve_supply_network
			target = scope:tut_supply_network
		}
	}
}
